    tables = image_patch.find("table")
    chairs = image_patch.find("chair")

    if not tables or not chairs:
        return image_patch

    white_tables = [t for t in tables if t.verify_property("table", "white")]
    wooden_tables = [t for t in white_tables if t.verify_property("table", "wooden")]

    small_chairs = [c for c in chairs if c.verify_property("chair", "small")]
    wooden_chairs = [c for c in small_chairs if c.verify_property("chair", "wooden")]

    if not wooden_tables or not wooden_chairs:
        return image_patch

    table_chair_pairs = [(t, c) for t in wooden_tables for c in wooden_chairs if distance(t, c) < 100]

    if not table_chair_pairs:
        return image_patch

    return min(table_chair_pairs, key=lambda pair: distance(pair[0], pair[1]))

